export type Subscription = { "awaiting_billing_schedule"?: boolean; /** Format: int32. */ "billing_anchor_day"?: number; /** How often the subscription bills, frozen when the subscription was created. Read with billing_interval_count: monthly with a count of 3 bills quarterly. Omitted for subscriptions created before Flint recorded this interval. */ "billing_interval"?: "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Number of billing_interval units between charges, frozen when the subscription was created. Omitted for subscriptions created before Flint recorded this interval. Format: int32. */ "billing_interval_count"?: number; /** maxItems: 12. */ "billing_interval_options"?: Array<SubscriptionIntervalOption>; "billing_schedule_owner": "flint" | "external" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "billing_schedule_waiting_started_at"?: string; /** What the buyer can do with the subscription, in this order: cancel, pause, resume, reactivate, update_payment_method, retry_payment, update_delivery, skip, update_billing_interval, update_quantity, swap_items, then renew, under the store's customer_account.buyer_capabilities. A buyer's read or change through a customer session on /v1/me, or in Flint's buyer account, lists all twelve every time; a merchant read gets an empty list. update_payment_method is required while a payment is past due, due by next_retry_at when a retry is scheduled, and when the card expires before next_billing_at, due by then. Example: []. */ "buyer_actions": Array<BuyerAction>; /** True when the subscription is scheduled to cancel at the end of the current period. Schedule with the cancel route and undo with the reactivate route. */ "cancel_at_period_end": boolean; /** RFC3339 timestamp. Format: date-time. */ "canceled_at"?: string; /** Who asked to cancel, when, and why. Present once a cancellation is requested, whether it takes effect at the end of the billing period or right away. Omitted when no one asked, such as a cancellation after failed payments, and removed when a scheduled cancellation is undone. */ "cancellation_details"?: SubscriptionCancellationDetails; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "completed_cycles": string; /** RFC3339 timestamp. Format: date-time. */ "contract_end_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "contract_start_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "current_period_end"?: string; "current_period_start"?: string; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_id": string; "delivery"?: SubscriptionDelivery; /** Current delivery issue that blocks collection. Mutually exclusive with upcoming_delivery_hold. */ "delivery_hold"?: SubscriptionDeliveryHold; /** Early termination fee frozen in the subscription's contract terms. Present only before contract_end_at when those terms include a fee. Later plan changes do not change this fee. */ "early_termination_fee_money"?: MoneyValue; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Renewal waiting for stock. Included only in merchant responses and omitted from buyer responses. */ "inventory_wait"?: SubscriptionInventoryWait; "line_items"?: Array<SubscriptionLineItem>; "merchant_id"?: string; "metadata"?: Record<string, string>; /** RFC3339 timestamp. Format: date-time. */ "next_billing_at"?: string; /** Recorded automatic payment retry time. Null when no retry time is available. Format: date-time. */ "next_retry_at"?: string | null; /** ID of the paid renewal order whose shipment has not been dispatched. It keeps its committed delivery destination after preference changes and cancellation. Absent when no such renewal order exists. Only renewal orders count; the signup order is not included. */ "open_renewal_order_id"?: string; "pause_reason"?: "buyer" | "delivery_action_required" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "paused_at"?: string; "payment_method"?: (({ "card"?: CardDetails; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "payment_method_id": string; "status": "pending" | "active" | "expired" | "removed" | "failed" | (string & {}); "type": "card" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "payment_method_id": string; /** Whole-number quantity; fractional quantities are not supported. Format: int32. */ "quantity": number; /** maxItems: 10. */ "quantity_options"?: Array<number>; /** What one billing period charges before tax and discounts, frozen when the subscription was created. Plan price changes after that do not change it. Omitted for subscriptions created before Flint recorded this amount. */ "recurring_amount_money"?: MoneyValue; /** Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "service_location"?: SubscriptionServiceLocation; /** RFC3339 timestamp. Format: date-time. */ "starts_at"?: string; "status": "trialing" | "active" | "paused" | "past_due" | "canceled" | "incomplete" | (string & {}); "subscription_id": string; "subscription_plan"?: (({ "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Format: int32. */ "billing_interval_count": number; /** maxItems: 12. */ "billing_interval_options"?: Array<SubscriptionIntervalOption>; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** ISO 4217 currency code. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; "description"?: string; "line_items"?: Array<SubscriptionPlanLineItem>; "name": string; /** maxItems: 10. */ "quantity_options"?: Array<number>; "setup_fee_money"?: MoneyValue; "status": "active" | "archived" | (string & {}); "subscription_plan_id": string; /** Format: int32. */ "trial_period_days"?: number; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "subscription_plan_id"?: string; "trial_end"?: string; /** Delivery issue forecast for the next renewal at renewal_at. Mutually exclusive with delivery_hold. */ "upcoming_delivery_hold"?: SubscriptionUpcomingDeliveryHold; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "version": string; };
